    ctx.globalAlpha = Math.min(1, alpha);
    ctx.globalCompositeOperation = "source-over";
    const rgb = LAYER_RGB[nd.layer];
    ctx.fillStyle = `rgb(${Math.round(rgb[0] * 0.35 + 165)},${Math.round(rgb[1] * 0.35 + 165)},${Math.round(rgb[2] * 0.35 + 165)})`;
